import { getCamelRandomId } from '../../../../camel-utils/camel-random-id';

export const kameletTemplate = () => {
  const kameletId = getCamelRandomId('kamelet');

  return `apiVersion: camel.apache.org/v1
kind: Kamelet
metadata:
  name: ${kameletId}
  annotations:
    camel.apache.org/kamelet.support.level: "Stable"
    camel.apache.org/catalog.version: "main-SNAPSHOT"
    camel.apache.org/kamelet.icon: "data:image/svg+xml;base64,"
    camel.apache.org/provider: "Apache Software Foundation"
    camel.apache.org/kamelet.group: "Users"
  labels:
    camel.apache.org/kamelet.type: "source"
spec:
  definition:
    title: ${kameletId}
    description: "Produces periodic events about random users!"
    type: object
    properties:
      period:
        title: Period
        description: The time interval between two events
        type: integer
        default: 5000
  types:
    out:
      mediaType: application/json
  dependencies:
    - "camel:timer"
    - "camel:http"
    - "camel:kamelet"
  template:
    from:
      id: ${getCamelRandomId('from')}
      uri: timer
      parameters:
        period: "{{period}}"
        timerName: user
      steps:
      - to:
          uri: https
          parameters:
            httpUri: random-data-api.com/api/v2/users
      - to: "kamelet:sink"`;
};
